"""검색 평가: recall@k 와 MRR 을 세 가지 설정 × 질문 유형별로 비교 — python evaluate.py eval.jsonl"""
import json
import sys
from collections import defaultdict

from hybrid import hybrid_search, vector_search
from rerank import rerank

K = 4


def key(r: dict) -> str:
    return f"{r['doc']}#{r['section']}"


def dedup(keys: list[str]) -> list[str]:
    """같은 섹션의 청크가 여러 개면 첫 번째만 셉니다 (근거 단위가 섹션이므로)."""
    return list(dict.fromkeys(keys))


RETRIEVERS = {
    "vector": lambda q: dedup([key(r) for r in vector_search(q, 20)]),
    "hybrid": lambda q: dedup([key(r) for r in hybrid_search(q, 20)]),
    "hybrid+rerank": lambda q: dedup([key(r) for _, r in rerank(q, hybrid_search(q, 20), top=10)]),
}


def recall_at_k(ranked: list[str], gold: set[str], k: int = K) -> float:
    """정답 근거 중 상위 k개 안에 들어온 비율."""
    return len(gold & set(ranked[:k])) / len(gold)


def reciprocal_rank(ranked: list[str], gold: set[str]) -> float:
    """첫 정답 근거의 순위 역수. 1위면 1.0, 3위면 0.33, 못 찾으면 0."""
    for i, k in enumerate(ranked, 1):
        if k in gold:
            return 1.0 / i
    return 0.0


def main(path: str):
    items = [json.loads(line) for line in open(path, encoding="utf-8") if line.strip()]
    items = [it for it in items if it["answerable"] and it["evidence"]]   # 검색 평가는 답이 있는 문항만
    types = sorted({it["type"] for it in items})
    rows = []
    print(f"{'설정':14s} {'전체':>14s} " + " ".join(f"{t:>14s}" for t in types))
    for name, retrieve in RETRIEVERS.items():
        rec, rr = defaultdict(list), defaultdict(list)
        for it in items:
            ranked, gold = retrieve(it["question"]), set(it["evidence"])
            for g in ("전체", it["type"]):
                rec[g].append(recall_at_k(ranked, gold))
                rr[g].append(reciprocal_rank(ranked, gold))
            if name == "hybrid+rerank":
                hit = next((i for i, k in enumerate(ranked, 1) if k in gold), None)
                rows.append({"id": it["id"], "type": it["type"], "category": it["category"],
                             "rank": hit, "top": ranked[:K]})
        cell = lambda g: f"R{sum(rec[g]) / len(rec[g]):.2f} M{sum(rr[g]) / len(rr[g]):.2f}"
        print(f"{name:14s} {cell('전체'):>14s} " + " ".join(f"{cell(t):>14s}" for t in types))
    print(f"(R = recall@{K}, M = MRR, 답이 있는 문항 {len(items)}개)")
    with open("eval_results.jsonl", "w", encoding="utf-8") as f:
        for row in rows:
            f.write(json.dumps(row, ensure_ascii=False) + "\n")
    print("문항별 결과 → eval_results.jsonl (rank 가 비었거나 4보다 큰 문항부터 원인을 봅니다)")


if __name__ == "__main__":
    main(sys.argv[1] if len(sys.argv) > 1 else "eval.jsonl")

package study.s10;

import dev.langchain4j.model.embedding.EmbeddingModel;
import org.apache.lucene.analysis.Analyzer;
import org.apache.lucene.analysis.ko.KoreanAnalyzer;
import org.apache.lucene.document.Document;
import org.apache.lucene.document.Field;
import org.apache.lucene.document.StoredField;
import org.apache.lucene.document.TextField;
import org.apache.lucene.index.DirectoryReader;
import org.apache.lucene.index.IndexWriter;
import org.apache.lucene.index.IndexWriterConfig;
import org.apache.lucene.index.StoredFields;
import org.apache.lucene.queryparser.classic.ParseException;
import org.apache.lucene.queryparser.classic.QueryParser;
import org.apache.lucene.search.IndexSearcher;
import org.apache.lucene.search.Query;
import org.apache.lucene.search.ScoreDoc;
import org.apache.lucene.search.similarities.BM25Similarity;
import org.apache.lucene.store.ByteBuffersDirectory;
import org.apache.lucene.store.Directory;
import study.s09.Ask;
import study.s09.Indexer;
import study.s09.Indexer.Chunk;

import java.io.IOException;
import java.util.*;
import java.util.function.Predicate;
import java.util.stream.IntStream;

/**
 * 하이브리드 검색: Lucene BM25 + 벡터를 RRF 로 합치기.
 * 실행: ./mvnw -q compile exec:java -Dexec.mainClass=study.s10.Hybrid -Dexec.args="ORA-00054"
 */
public final class Hybrid {

    static final int RRF_K = 60;     // RRF 상수. 원 논문(Cormack 외, 2009) 값
    static final int POOL = 50;      // 각 검색기에서 가져올 후보 수

    public final List<Chunk> records;
    final EmbeddingModel embedder;
    final Analyzer analyzer = new KoreanAnalyzer();   // Nori: 조사·어미를 떼고 명사·동사 어간만 색인
    final IndexSearcher searcher;

    public Hybrid() throws IOException {
        records = Indexer.load();
        embedder = Indexer.model();
        // rank_bm25(Python 트랙)의 기본값 k1=1.5, b=0.75 에 맞춥니다. Lucene 기본값은 k1=1.2
        BM25Similarity bm25 = new BM25Similarity(1.5f, 0.75f);
        Directory dir = new ByteBuffersDirectory();       // 메모리 색인 (청크 수만 개까지 충분)
        try (IndexWriter w = new IndexWriter(dir, new IndexWriterConfig(analyzer).setSimilarity(bm25))) {
            for (int i = 0; i < records.size(); i++) {
                Document d = new Document();
                d.add(new StoredField("idx", i));
                d.add(new TextField("text", records.get(i).text(), Field.Store.NO));
                w.addDocument(d);
            }
        }
        searcher = new IndexSearcher(DirectoryReader.open(dir));
        searcher.setSimilarity(bm25);
    }

    List<Integer> vectorRank(String question, int n) {
        float[] q = embedder.embed("query: " + question).content().vector();
        double[] s = records.stream().mapToDouble(c -> Ask.dot(q, c.vector())).toArray();
        return IntStream.range(0, s.length).boxed()
                .sorted((a, b) -> Double.compare(s[b], s[a])).limit(n).toList();
    }

    List<Integer> bm25Rank(String question, int n) throws IOException {
        Query query;
        try {
            // ORA-00054 의 '-' 같은 연산자 글자를 이스케이프해 질문을 그대로 검색어로 씁니다 (기본 OR)
            query = new QueryParser("text", analyzer).parse(QueryParser.escape(question));
        } catch (ParseException e) {
            return List.of();                          // 분석 후 남는 낱말이 없으면 BM25 후보 없음
        }
        StoredFields stored = searcher.storedFields();
        List<Integer> out = new ArrayList<>();
        for (ScoreDoc sd : searcher.search(query, n).scoreDocs) {
            out.add(stored.document(sd.doc).getField("idx").numericValue().intValue());
        }
        return out;
    }

    /** 순위만 보고 합칩니다: 점수 = Σ 1 / (k + 순위). 점수 척도가 달라도 섞을 수 있습니다. */
    public static List<Integer> rrf(List<List<Integer>> rankings) {
        Map<Integer, Double> fused = new HashMap<>();
        for (List<Integer> ranking : rankings) {
            for (int r = 0; r < ranking.size(); r++) fused.merge(ranking.get(r), 1.0 / (RRF_K + r + 1), Double::sum);
        }
        return fused.entrySet().stream()
                .sorted(Map.Entry.<Integer, Double>comparingByValue().reversed())
                .map(Map.Entry::getKey).toList();
    }

    public List<Integer> hybridIds(String question, int n, Predicate<Chunk> where) throws IOException {
        return rrf(List.of(vectorRank(question, POOL), bm25Rank(question, POOL))).stream()
                .filter(i -> where == null || where.test(records.get(i)))   // 메타데이터 필터 (예: 구판 제외)
                .limit(n).toList();
    }

    public List<Chunk> hybridSearch(String question, int n, Predicate<Chunk> where) throws IOException {
        return hybridIds(question, n, where).stream().map(records::get).toList();
    }

    public List<Chunk> vectorSearch(String question, int n) {
        return vectorRank(question, n).stream().map(records::get).toList();
    }

    /** EXCLUDE_DOC=batch-ops-manual-v2.md 처럼 환경변수로 문서를 빼는 필터 */
    public static Predicate<Chunk> whereFromEnv() {
        String ex = System.getenv("EXCLUDE_DOC");
        return ex == null ? null : c -> !c.doc().equals(ex);
    }

    static List<String> keys(List<Chunk> cs) {
        return cs.stream().map(c -> c.doc() + "#" + c.section()).toList();
    }

    public static void main(String[] args) throws IOException {
        String q = args.length > 0 ? String.join(" ", args) : "Terrastream 콘솔에서 재실행";
        Hybrid h = new Hybrid();
        System.out.println("벡터만   : " + keys(h.vectorSearch(q, 5)));
        System.out.println("하이브리드: " + keys(h.hybridSearch(q, 5, whereFromEnv())));
    }
}

package study.s10;

import ai.onnxruntime.OrtSession;
import dev.langchain4j.data.segment.TextSegment;
import dev.langchain4j.model.scoring.onnx.OnnxScoringModel;
import study.s09.Ask.Hit;
import study.s09.Indexer.Chunk;

import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

/**
 * 리랭킹: 후보 청크를 cross-encoder(bge-reranker-v2-m3, ONNX)로 다시 채점.
 * 실행: ./mvnw -q compile exec:java -Dexec.mainClass=study.s10.Reranker -Dexec.args="배치 실패하면 처음부터 다시 돌려요?"
 */
public final class Reranker implements AutoCloseable {

    private final OnnxScoringModel model;

    public Reranker() throws Exception {
        Path dir = Path.of(System.getenv().getOrDefault("RERANK_DIR", "models/bge-reranker-v2-m3"));
        // 마지막 인자 true = 시그모이드 적용 → 0~1 점수 (Python 트랙 CrossEncoder 와 같은 척도)
        this.model = new OnnxScoringModel(dir.resolve("model.onnx").toString(), new OrtSession.SessionOptions(),
                dir.resolve("tokenizer.json").toString(), 510, true);
    }

    /** 질문과 청크를 한 쌍으로 모델에 넣어 관련도를 받고, 높은 순으로 top 개만 남깁니다. */
    public List<Hit> rerank(String question, List<Chunk> candidates, int top) {
        if (candidates.isEmpty()) return List.of();
        List<TextSegment> segs = candidates.stream().map(c -> TextSegment.from(c.text())).toList();
        List<Double> scores = model.scoreAll(segs, question).content();
        List<Hit> hits = new ArrayList<>();
        for (int i = 0; i < candidates.size(); i++) hits.add(new Hit(scores.get(i), candidates.get(i)));
        hits.sort(Comparator.comparingDouble(Hit::score).reversed());
        return hits.subList(0, Math.min(top, hits.size()));
    }

    @Override
    public void close() {
        model.close();                 // 네이티브(ONNX Runtime) 자원 해제
    }

    public static void main(String[] args) throws Exception {
        String q = args.length > 0 ? String.join(" ", args) : "배치가 30분 넘게 안 돌아오면 누구한테 전화하나요?";
        Hybrid h = new Hybrid();
        try (Reranker r = new Reranker()) {
            for (Hit hit : r.rerank(q, h.hybridSearch(q, 20, null), 4)) {
                System.out.printf("%.3f  %s › %s%n", hit.score(), hit.chunk().doc(), hit.chunk().section());
            }
        }
    }
}

package study.s10;

import com.anthropic.client.AnthropicClient;
import com.anthropic.client.okhttp.AnthropicOkHttpClient;
import com.anthropic.models.messages.Message;
import com.anthropic.models.messages.MessageCreateParams;
import com.anthropic.models.messages.TextBlock;
import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import study.s09.Ask;
import study.s09.Ask.Hit;
import study.s09.Indexer.Chunk;

import java.util.*;
import java.util.function.Predicate;
import java.util.regex.Pattern;
import java.util.stream.Collectors;

/**
 * 질의 재작성 + 하이브리드 + 리랭킹 + 가드레일로 답하기.
 * 실행: ./mvnw -q compile exec:java -Dexec.mainClass=study.s10.Guard -Dexec.args="TSS 재처리는 어디서부터 하나요?"
 */
public final class Guard implements AutoCloseable {

    static final double MIN_RERANK = 0.30;   // 최상위 근거 점수가 이보다 낮으면 답하지 않음 (평가셋으로 조정)

    // 업무 용어사전: 약어 → 문서에 실제로 쓰인 표현 (세션 12에서 정비하는 그 사전)
    static final Map<String, String> GLOSSARY = new LinkedHashMap<>(Map.of(
            "TSS", "Terrastream", "당직", "운영 당직자", "재처리", "재실행", "임시 공간", "TEMP 테이블스페이스"));

    record Rule(Pattern pattern, String label) {}

    static final List<Rule> PII = List.of(
            new Rule(Pattern.compile("\\b\\d{6}-?[1-4]\\d{6}\\b"), "[주민번호]"),
            new Rule(Pattern.compile("\\b01[016789]-?\\d{3,4}-?\\d{4}\\b"), "[전화번호]"),
            new Rule(Pattern.compile("[\\w.+-]+@[\\w-]+\\.[\\w.]+"), "[이메일]"),
            new Rule(Pattern.compile("\\b\\d{3,6}-\\d{2,6}-\\d{4,8}\\b"), "[계좌번호]"));
    static final Pattern CITED = Pattern.compile("\\[\\d+\\]");

    final AnthropicClient client = AnthropicOkHttpClient.fromEnv();
    final ObjectMapper json = new ObjectMapper();
    final Hybrid hybrid;
    final Reranker reranker;

    public Guard() throws Exception {
        hybrid = new Hybrid();
        reranker = new Reranker();
    }

    /** 응답에 thinking 블록이 먼저 올 수 있으므로 text 블록만 모읍니다. */
    static String textOf(Message msg) {
        return msg.content().stream().flatMap(b -> b.text().stream()).map(TextBlock::text).collect(Collectors.joining());
    }

    String ask(String system, String user, int maxTokens) {
        return textOf(client.messages().create(MessageCreateParams.builder()
                .model(Ask.MODEL).maxTokens(maxTokens).system(system).addUserMessage(user).build()));
    }

    static String mask(String text) {
        for (Rule r : PII) text = r.pattern().matcher(text).replaceAll(r.label());
        return text;
    }

    /** 원 질문 + 용어사전 치환본 + LLM 이 만든 검색어 2개. */
    List<String> rewrite(String question) {
        String expanded = question;
        for (var e : GLOSSARY.entrySet()) expanded = expanded.replace(e.getKey(), e.getKey() + "(" + e.getValue() + ")");
        String text = ask("사내 문서 검색어를 만듭니다. 질문을 문서에 나올 법한 표현으로 바꾼 검색어 2개를 "
                + "JSON 문자열 배열로만 출력하세요. 예: [\"...\", \"...\"]", expanded, 200);
        List<String> extra = List.of();
        try {
            extra = json.readValue(text.substring(text.indexOf('['), text.lastIndexOf(']') + 1),
                    new TypeReference<List<String>>() {});
        } catch (Exception e) {
            // 파싱 실패 시 원 질문과 치환본만 씁니다
        }
        LinkedHashSet<String> qs = new LinkedHashSet<>(List.of(question, expanded));
        qs.addAll(extra.subList(0, Math.min(2, extra.size())));
        return new ArrayList<>(qs);
    }

    public Map<String, Object> answer(String rawQuestion, Predicate<Chunk> where) throws Exception {
        String question = mask(rawQuestion);                         // 1) 입력 마스킹: 외부 LLM 로 나가기 전에
        List<String> queries = rewrite(question);                    // 2) 질의 재작성
        List<List<Integer>> lists = new ArrayList<>();
        for (String q : queries) lists.add(hybrid.hybridIds(q, 20, where));   // 3) 검색어별 결과를 다시 RRF
        List<Chunk> pool = Hybrid.rrf(lists).stream().limit(20).map(hybrid.records::get).toList();
        List<Hit> picked = reranker.rerank(question, pool, 4);       // 4) 리랭킹

        Map<String, Object> out = new LinkedHashMap<>();
        out.put("question", question);
        out.put("queries", queries);
        if (picked.isEmpty() || picked.get(0).score() < MIN_RERANK) { // 5) 근거 없음 처리
            out.put("grounded", false);
            out.put("sources", List.of());
            out.put("answer", "문서에서 확실한 근거를 찾지 못했습니다. 운영 당직자에게 문의해 주세요.");
            return out;
        }
        StringBuilder ctx = new StringBuilder();
        for (int n = 0; n < picked.size(); n++) {
            Chunk c = picked.get(n).chunk();
            ctx.append("[").append(n + 1).append("] (").append(c.doc()).append(" · ").append(c.section())
                    .append(")\n").append(c.text()).append("\n\n");
        }
        String text = mask(ask(Ask.SYSTEM, "<근거>\n" + ctx.toString().strip() + "\n</근거>\n\n질문: " + question, 800));  // 6) 출력 마스킹
        out.put("grounded", CITED.matcher(text).find());
        out.put("answer", text);
        out.put("sources", picked.stream().map(h -> Map.of("doc", h.chunk().doc(), "section", h.chunk().section(),
                "score", Math.round(h.score() * 1000) / 1000.0)).toList());
        return out;
    }

    @Override
    public void close() {
        reranker.close();
    }

    public static void main(String[] args) throws Exception {
        String q = args.length > 0 ? String.join(" ", args) : "TSS 재처리는 어디서부터 하나요?";
        try (Guard g = new Guard()) {
            System.out.println(g.json.writerWithDefaultPrettyPrinter().writeValueAsString(g.answer(q, Hybrid.whereFromEnv())));
        }
    }
}

package study.s10;

import com.fasterxml.jackson.annotation.JsonIgnoreProperties;
import com.fasterxml.jackson.databind.ObjectMapper;
import study.s09.Indexer.Chunk;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.*;
import java.util.function.Function;

/**
 * 검색 평가: recall@k 와 MRR 을 세 가지 설정 × 질문 유형별로 비교 (LLM 호출 없음).
 * 실행: ./mvnw -q compile exec:java -Dexec.mainClass=study.s10.Evaluate -Dexec.args=eval.jsonl
 */
public final class Evaluate {

    static final int K = 4;

    @JsonIgnoreProperties(ignoreUnknown = true)
    public record Item(String id, String type, String question, String answer, List<String> evidence,
                       String category, boolean answerable) {}

    static final ObjectMapper JSON = new ObjectMapper();

    public static List<Item> load(Path path) throws IOException {
        List<Item> items = new ArrayList<>();
        for (String line : Files.readAllLines(path, StandardCharsets.UTF_8)) {
            if (!line.isBlank()) items.add(JSON.readValue(line, Item.class));
        }
        return items;
    }

    /** 같은 섹션의 청크가 여러 개면 첫 번째만 셉니다 (근거 단위가 섹션이므로). */
    static List<String> dedupKeys(List<Chunk> chunks) {
        return new ArrayList<>(new LinkedHashSet<>(chunks.stream().map(c -> c.doc() + "#" + c.section()).toList()));
    }

    /** 정답 근거 중 상위 k개 안에 들어온 비율. */
    static double recallAtK(List<String> ranked, Set<String> gold) {
        Set<String> top = new HashSet<>(ranked.subList(0, Math.min(K, ranked.size())));
        return gold.stream().filter(top::contains).count() / (double) gold.size();
    }

    /** 첫 정답 근거의 순위 역수. 1위면 1.0, 3위면 0.33, 못 찾으면 0. */
    static double reciprocalRank(List<String> ranked, Set<String> gold) {
        for (int i = 0; i < ranked.size(); i++) if (gold.contains(ranked.get(i))) return 1.0 / (i + 1);
        return 0.0;
    }

    interface Retriever {
        List<String> apply(String q) throws IOException;
    }

    public static void main(String[] args) throws Exception {
        List<Item> items = load(Path.of(args.length > 0 ? args[0] : "eval.jsonl")).stream()
                .filter(it -> it.answerable() && !it.evidence().isEmpty())   // 검색 평가는 답이 있는 문항만
                .toList();
        Hybrid h = new Hybrid();
        try (Reranker rr = new Reranker()) {
            Map<String, Retriever> retrievers = new LinkedHashMap<>();
            retrievers.put("vector", q -> dedupKeys(h.vectorSearch(q, 20)));
            retrievers.put("hybrid", q -> dedupKeys(h.hybridSearch(q, 20, null)));
            retrievers.put("hybrid+rerank", q -> dedupKeys(rr.rerank(q, h.hybridSearch(q, 20, null), 10)
                    .stream().map(x -> x.chunk()).toList()));

            List<String> types = items.stream().map(Item::type).distinct().sorted().toList();
            List<String> groups = new ArrayList<>(List.of("전체"));
            groups.addAll(types);
            System.out.printf("%-14s%s%n", "설정", String.join("", groups.stream().map(g -> "%15s".formatted(g)).toList()));
            List<Map<String, Object>> rows = new ArrayList<>();

            for (var e : retrievers.entrySet()) {
                Map<String, List<Double>> rec = new HashMap<>(), mrr = new HashMap<>();
                for (Item it : items) {
                    List<String> ranked = e.getValue().apply(it.question());
                    Set<String> gold = new HashSet<>(it.evidence());
                    for (String g : List.of("전체", it.type())) {
                        rec.computeIfAbsent(g, x -> new ArrayList<>()).add(recallAtK(ranked, gold));
                        mrr.computeIfAbsent(g, x -> new ArrayList<>()).add(reciprocalRank(ranked, gold));
                    }
                    if (e.getKey().equals("hybrid+rerank")) {
                        int hit = -1;
                        for (int i = 0; i < ranked.size() && hit < 0; i++) if (gold.contains(ranked.get(i))) hit = i + 1;
                        Map<String, Object> row = new LinkedHashMap<>();
                        row.put("id", it.id());
                        row.put("type", it.type());
                        row.put("category", it.category());
                        row.put("rank", hit < 0 ? null : hit);
                        row.put("top", ranked.subList(0, Math.min(K, ranked.size())));
                        rows.add(row);
                    }
                }
                Function<String, String> cell = g -> "R%.2f M%.2f".formatted(avg(rec.get(g)), avg(mrr.get(g)));
                System.out.printf("%-14s%s%n", e.getKey(), String.join("", groups.stream().map(g -> "%15s".formatted(cell.apply(g))).toList()));
            }
            System.out.printf("(R = recall@%d, M = MRR, 답이 있는 문항 %d개)%n", K, items.size());
            List<String> lines = new ArrayList<>();
            for (Map<String, Object> row : rows) lines.add(JSON.writeValueAsString(row));
            Files.write(Path.of("eval_results.jsonl"), lines, StandardCharsets.UTF_8);
            System.out.println("문항별 결과 → eval_results.jsonl (rank 가 비었거나 4보다 큰 문항부터 원인을 봅니다)");
        }
    }

    static double avg(List<Double> xs) {
        return xs == null || xs.isEmpty() ? 0 : xs.stream().mapToDouble(Double::doubleValue).average().orElse(0);
    }
}

package study.s10;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import study.s09.Ask;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.*;

/**
 * 답변 평가: LLM 판정(기준표) + 사람 검수 목록 (24문항 기준 LLM 호출 약 70회).
 * 실행: ./mvnw -q compile exec:java -Dexec.mainClass=study.s10.Judge -Dexec.args=eval.jsonl
 */
public final class Judge {

    static final String JUDGE_MODEL = System.getenv().getOrDefault("JUDGE_MODEL", Ask.MODEL);

    static final String RUBRIC = """
            당신은 사내 문서 Q&A 봇의 답변을 채점하는 평가자입니다. 아래 기준으로만 채점하세요.
            - correct (0~2): 정답 요지와 비교. 2=핵심이 모두 맞음, 1=일부만 맞거나 불필요한 내용 섞임, 0=틀림.
              정답 요지가 비어 있으면 '문서에 없는 질문'이므로, 답하지 않고 모른다고 하면 2, 지어내면 0.
            - faithful (0~2): 답변의 모든 문장이 제공된 근거로 뒷받침되는가. 2=전부, 1=일부 근거 밖, 0=대부분 근거 밖.
            - cited (0~1): 답변 문장에 [번호] 출처가 붙어 있는가. 거절 답변이면 1.
            JSON 한 줄로만 답하세요: {"correct": n, "faithful": n, "cited": n, "reason": "한 문장"}""";

    static String csv(Object v) {
        String s = v == null ? "" : v.toString();
        return "\"" + s.replace("\"", "\"\"") + "\"";
    }

    public static void main(String[] args) throws Exception {
        List<Evaluate.Item> items = Evaluate.load(Path.of(args.length > 0 ? args[0] : "eval.jsonl"));
        ObjectMapper json = new ObjectMapper();
        List<Map<String, Object>> results = new ArrayList<>();

        try (Guard guard = new Guard()) {
            for (Evaluate.Item it : items) {
                Map<String, Object> out = guard.answer(it.question(), null);
                @SuppressWarnings("unchecked")
                List<Map<String, Object>> sources = (List<Map<String, Object>>) out.get("sources");
                StringBuilder src = new StringBuilder();
                for (Map<String, Object> s : sources) src.append("- ").append(s.get("doc")).append(" › ").append(s.get("section")).append("\n");
                String prompt = "질문: " + it.question() + "\n정답 요지: " + it.answer() + "\n사용된 근거:\n"
                        + (src.isEmpty() ? "(없음)\n" : src) + "\n봇 답변:\n" + out.get("answer");
                // Claude 5.5 계열은 temperature 를 받지 않습니다. 대신 기준표를 구체적으로 적어 흔들림을 줄입니다.
                String text = Guard.textOf(guard.client.messages().create(com.anthropic.models.messages.MessageCreateParams.builder()
                        .model(JUDGE_MODEL).maxTokens(1000).system(RUBRIC).addUserMessage(prompt).build()));

                Map<String, Object> row = new LinkedHashMap<>();
                row.put("id", it.id());
                row.put("category", it.category());
                row.put("answerable", it.answerable());
                row.put("bot", out.get("answer"));
                row.put("grounded", out.get("grounded"));
                try {
                    JsonNode score = json.readTree(text.substring(text.indexOf('{'), text.lastIndexOf('}') + 1));
                    row.put("correct", score.path("correct").asInt());
                    row.put("faithful", score.path("faithful").asInt());
                    row.put("cited", score.path("cited").asInt());
                    row.put("reason", score.path("reason").asText());
                } catch (Exception e) {
                    row.put("correct", null);
                    row.put("faithful", null);
                    row.put("cited", null);
                    row.put("reason", "판정 파싱 실패: " + text.substring(0, Math.min(80, text.length())));
                }
                results.add(row);
                System.out.printf("%s correct=%s faithful=%s%n", it.id(), row.get("correct"), row.get("faithful"));
            }
        }

        List<Map<String, Object>> ok = results.stream().filter(r -> r.get("correct") != null).toList();
        double acc = ok.stream().filter(r -> Integer.valueOf(2).equals(r.get("correct"))).count() / (double) Math.max(ok.size(), 1);
        double faith = ok.stream().filter(r -> Integer.valueOf(2).equals(r.get("faithful"))).count() / (double) Math.max(ok.size(), 1);
        System.out.printf("정답률 %.0f%% · 근거 충실 %.0f%% · 채점 %d/%d건%n", acc * 100, faith * 100, ok.size(), results.size());

        List<String> lines = new ArrayList<>();
        for (Map<String, Object> r : results) lines.add(json.writeValueAsString(r));
        Files.write(Path.of("judge_results.jsonl"), lines, StandardCharsets.UTF_8);

        // 사람 검수: 낮은 점수·파싱 실패는 전부, 나머지는 무작위 20%
        Random random = new Random(42);
        List<String> fields = List.of("id", "category", "bot", "correct", "faithful", "reason", "사람판정", "메모");
        StringBuilder sheet = new StringBuilder("﻿" + String.join(",", fields) + "\n");   // 엑셀용 BOM
        int n = 0;
        for (Map<String, Object> r : results) {
            if (!Integer.valueOf(2).equals(r.get("correct")) || random.nextDouble() < 0.2) {
                sheet.append(String.join(",", fields.stream().map(f -> csv(r.getOrDefault(f, ""))).toList())).append("\n");
                n++;
            }
        }
        Files.writeString(Path.of("human_review.csv"), sheet, StandardCharsets.UTF_8);
        System.out.println("사람 검수 대상 " + n + "건 → human_review.csv (엑셀로 열어 '사람판정' 열을 채웁니다)");
    }
}

"""실패 유형별로 묶어 개선 우선순위표 만들기 — python report.py
evaluate.py(eval_results.jsonl) 와 judge.py(judge_results.jsonl) 를 먼저 실행합니다.
"""
import json
from collections import Counter

ACTION = {
    "검색 실패": "용어사전·동의어 보강, 청크 제목 확인, BM25 가중, 문서 누락 여부 확인",
    "생성 실패": "프롬프트 지시 보강, 리랭커 top 조정, 근거 순서·길이 확인",
    "거절 실패": "리랭커 점수 하한선 올리기, 거절 문구 명시, 범위 밖 예시 추가",
}


def load(path: str) -> dict:
    return {r["id"]: r for r in map(json.loads, open(path, encoding="utf-8"))}


def classify(j: dict, e: dict | None) -> str | None:
    if j["correct"] == 2:
        return None
    if not j["answerable"]:
        return "거절 실패"                    # 문서에 없는데 답을 지어냄
    if e is None or e["rank"] is None or e["rank"] > 4:
        return "검색 실패"                    # 정답 근거가 상위 4개 안에 없음
    return "생성 실패"                        # 근거는 있었는데 답이 틀림


def main():
    judged, retrieved = load("judge_results.jsonl"), load("eval_results.jsonl")
    fails = Counter()
    for qid, j in judged.items():
        kind = classify(j, retrieved.get(qid))
        if kind:
            fails[(kind, j["category"])] += 1
    total = len(judged)
    correct = sum(j["correct"] == 2 for j in judged.values())
    print(f"전체 {total}문항 · 정답 {correct} ({correct / total:.0%})\n")
    print("| 순위 | 실패 유형 | 업무 분류 | 건수 | 먼저 할 일 |")
    print("|---|---|---|---|---|")
    for n, ((kind, cat), cnt) in enumerate(fails.most_common(), 1):
        print(f"| {n} | {kind} | {cat} | {cnt} | {ACTION[kind]} |")


if __name__ == "__main__":
    main()
